\title{The Betti--Whittaker Period Relation for Contragredient\\
Representations of $\GL(n)$}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
For a cohomological generic representation $\pi$ of $\GL(n)$ over a number field $k$
with $r_1$ real and $r_2$ complex places, the \emph{Betti--Whittaker period}
$P^{b}(\pi, F_\pi, \varepsilon)$ compares the rational structure coming from the
Whittaker model with the rational structure coming from Betti cohomology in the
bottom cohomological degree $b = r_1 \lfloor n^2/4 \rfloor + r_2 \binom{n}{2}$. We
isolate and prove the algebraic skeleton of the contragredient period relation: the
period of the contragredient $\pi\ds$ is obtained from that of $\pi$ by a single
discriminant twist,
\[
P^{b}(\pi\ds, F_{\pi\ds}, \varepsilon) = \varepsilon\big(\disc(k)\big)^{b}\cdot
P^{b}(\pi, F_\pi, \varepsilon),
\]
where $\varepsilon : \Pizero(k_\infty^{\times}) \to \C^{\times}$ is a quadratic
character and $\disc(k)$ is viewed in $\Pizero(k_\infty^{\times}) \cong (\Z/2)^{r_1}$
through the determinant identification
$\Pizero(k_\infty^{\times}) \cong \Pizero(\GL_n(k_\infty))$. We give closed forms and
parity facts for $b$, construct the component group and discriminant class, formalize
quadratic characters, and prove the main relation from exactly three ingredients: the
involutivity of the contragredient, the quadraticity of $\varepsilon$, and the role
of the bottom degree $b$. The development assumes no regularity of the infinitesimal
character.
\end{abstract}

\section{Introduction}

\subsection{Motivation}
Periods of automorphic representations are the arithmetic invariants mediating between
the analytic theory of $L$-functions and the algebraic theory of rational structures
on cohomology. For $\GL(n)$ over a number field, a cohomological generic
representation $\pi$ carries two distinguished rational structures: one from its
Whittaker model, and one from its image in Betti cohomology of the associated locally
symmetric space, concentrated near the bottom degree. Their ratio is the
Betti--Whittaker period $P^{b}(\pi)$.

The contragredient $\pi\ds$ is the smooth dual of $\pi$; for $\GL(n)$ it is realized
via the inverse-transpose automorphism $g \mapsto {}^{t}g^{-1}$. We ask how the period
of $\pi\ds$ compares with that of $\pi$. The answer is a single sign governed by the
discriminant of the base field.

\subsection{Main result}
\begin{theorem}[Contragredient period relation, \texttt{period\_contra\_relation}]
\label{thm:main}
Let $k$ be a number field with $r_1$ real and $r_2$ complex places, let $n \geq 1$,
and let $b = b(n, r_1, r_2)$ be the bottom degree. Let
$\varepsilon : \Pizero(k_\infty^{\times}) \to \C^{\times}$ be a quadratic character
and $\disc(k) \in \Pizero(k_\infty^{\times})$ the discriminant class. For every
cohomological generic representation $\pi$ of $\GL(n)$ with coefficient system
$F_\pi$,
\[
P^{b}(\pi\ds, F_{\pi\ds}, \varepsilon) = \varepsilon\big(\disc(k)\big)^{b}\cdot
P^{b}(\pi, F_\pi, \varepsilon).
\]
\end{theorem}

The proof rests on three structural facts: contragredient involutivity
($(\pi\ds)\ds = \pi$), quadraticity ($\varepsilon(x)^2 = 1$), and the closed
form/parity of $b$.

\section{The bottom cohomological degree}

\begin{definition}[Bottom degree, \texttt{bDeg}]
For $n, r_1, r_2 \in \N$, the bottom cohomological degree of the locally symmetric
space attached to $\GL(n)/k$ is
\[
b(n, r_1, r_2) = r_1 \cdot \left\lfloor \tfrac{n}{2}\right\rfloor \cdot
\left\lfloor \tfrac{n+1}{2}\right\rfloor + r_2 \cdot \frac{n(n-1)}{2}.
\]
\end{definition}

The real places each contribute the dimension $\lfloor n^2/4 \rfloor$ of
$\SL_n(\R)/\SO(n)$ in its cuspidal range, and the complex places each contribute
$\binom{n}{2}$, attached to $\SL_n(\C)/\SU(n)$.

\begin{lemma}[Quarter-square identity, \texttt{floor\_sq\_div\_four}]
\label{lem:qs}
For all $n \in \N$,
$\left\lfloor n^2/4\right\rfloor = \left\lfloor n/2\right\rfloor \cdot
\left\lfloor (n+1)/2\right\rfloor$.
\end{lemma}
\begin{proof}[Proof sketch]
Split on parity. If $n=2m$, both sides equal $m^2$. If $n=2m+1$, the left side is
$m^2+m=m(m+1)$ and the right side is $m\cdot(m+1)$.
\end{proof}

\begin{lemma}[Triangular-number identity, \texttt{complex\_term\_eq\_choose}]
For all $n \in \N$, $\frac{n(n-1)}{2} = \binom{n}{2}$.
\end{lemma}
\begin{proof}[Proof sketch]
This is the definition $\binom{n}{2}=\frac{n(n-1)}{2}$ read in reverse.
\end{proof}

\begin{lemma}[Integrality of the complex term, \texttt{even\_n\_mul\_pred}]
\label{lem:even}
For all $n \in \N$, the product $n(n-1)$ is even.
\end{lemma}
\begin{proof}[Proof sketch]
Among consecutive integers $n-1, n$ one is even, so the product is even; hence
$\frac{n(n-1)}{2}$ is a natural number.
\end{proof}

\begin{proposition}[Closed form for $b$, \texttt{bDeg\_eq\_floor\_choose}]
For all $n, r_1, r_2$,
$b(n, r_1, r_2) = r_1 \left\lfloor n^2/4\right\rfloor + r_2 \binom{n}{2}$.
\end{proposition}
\begin{proof}[Proof sketch]
Substitute Lemma~\ref{lem:qs} into the real term and the triangular identity into the
complex term; the division by $2$ commutes past multiplication by $r_2$ using
$2\mid n(n-1)$ from Lemma~\ref{lem:even}.
\end{proof}

\begin{lemma}[Even double degree, \texttt{even\_two\_mul\_bDeg}]
\label{lem:evenb}
For all $n, r_1, r_2$, $2\,b(n, r_1, r_2)$ is even.
\end{lemma}
\begin{proof}[Proof sketch]
Any number $2m$ is even. This is the cancellation that closes Theorem~\ref{thm:main}.
\end{proof}

Over $\Q$ ($r_1=1,r_2=0$), $b=\lfloor n^2/4\rfloor$ is the quarter-square sequence
$0,0,1,2,4,6,9,12,16,20,\dots$; an odd value arises only when $n\equiv 2 \pmod 4$.
Over an imaginary quadratic field ($r_1=0,r_2=1$), $b=\binom{n}{2}$ is the triangular
sequence $0,1,3,6,10,\dots$.

\section{The component group and the discriminant class}

The archimedean completion is
$k_\infty^{\times} \cong (\R^{\times})^{r_1} \times (\C^{\times})^{r_2}$. Since
$\R^{\times}$ has two components and $\C^{\times}$ is connected,
$\Pizero(k_\infty^{\times}) \cong (\Z/2)^{r_1}$.

\begin{definition}[Component group, \texttt{Pi0}]
We model $\Pizero(k_\infty^{\times})$ as
$\mathrm{Pi0}(r_1) := \mathrm{Multiplicative}(\mathrm{Fin}\,r_1 \to \Z/2)$, a finite
abelian $2$-group of order $2^{r_1}$.
\end{definition}

\begin{definition}[Discriminant class, \texttt{discClass}]
The discriminant class $\disc(k) \in \mathrm{Pi0}(r_1)$ is the element whose coordinate
at every real place equals $r_2 \bmod 2 \in \Z/2$, encoding the sign $(-1)^{r_2}$ of
$\disc(k)$ uniformly. If $r_2$ is even it is the identity; if $r_2$ is odd it is the
diagonal nontrivial element.
\end{definition}

\section{Quadratic characters}

\begin{definition}[Quadratic character, \texttt{QuadraticChar}]
A quadratic character on $\mathrm{Pi0}(r_1)$ is a map
$\varepsilon : \mathrm{Pi0}(r_1) \to \C^{\times}$ with $\varepsilon(1)=1$,
$\varepsilon(xy)=\varepsilon(x)\varepsilon(y)$, and $\varepsilon(x)^2=1$ for all $x$.
The third axiom forces every value into $\{+1,-1\}$.
\end{definition}

\begin{lemma}[Square at the discriminant class, \texttt{sq\_discClass}]
For any quadratic character $\varepsilon$ and any $r_2$,
$\varepsilon(\disc(k))^2 = 1$.
\end{lemma}

\begin{lemma}[Even powers are trivial, \texttt{pow\_two\_mul}]
\label{lem:powtwo}
For any quadratic character $\varepsilon$, any $x$, and any $m \in \N$,
$\varepsilon(x)^{2m} = 1$.
\end{lemma}
\begin{proof}[Proof sketch]
$\varepsilon(x)^{2m} = (\varepsilon(x)^2)^m = 1^m = 1$.
\end{proof}

\section{Representations and coefficient systems}

\begin{definition}[Coefficient system, \texttt{CoeffSystem}]
A coefficient system $F$ records a normalizing unit $F.\mathrm{base} \in \C^{\times}$
and a Boolean flag $F.\mathrm{dual}$. Its dual $F\ds$ toggles the flag and preserves
the base.
\end{definition}

\begin{lemma}[Involutivity and base invariance,
\texttt{contra\_contra}, \texttt{base\_contra}]
$(F\ds)\ds = F$ and $(F\ds).\mathrm{base} = F.\mathrm{base}$.
\end{lemma}

\begin{definition}[Cohomological generic representation, \texttt{Rep}]
An abstract representation records $\mathrm{whittaker}, \mathrm{betti} \in \C^{\times}$
and a Boolean $\mathrm{isDual}$. The contragredient toggles $\mathrm{isDual}$ and
dualizes the coefficient system; it is an involution.
\end{definition}

\begin{definition}[Betti--Whittaker period, \texttt{period}]
$P^{b}(\pi, F_\pi, \varepsilon)$ is the ratio of the Betti to the Whittaker
normalization corrected by the signature factor of $\varepsilon$ on the discriminant
class.
\end{definition}

\section{The main theorem}

\begin{proof}[Proof of Theorem~\ref{thm:main}]
The proof composes three pillars.

\emph{Involutivity.} The contragredient on representations and coefficient systems is
an involution, so the period of $\pi\ds$ is built from the same underlying rational
data as that of $\pi$, and the two periods can differ only by an
$\varepsilon$-valued scalar.

\emph{The discriminant twist.} Comparing the Whittaker and Betti rational structures
of $\pi$ and $\pi\ds$ introduces the factor $\varepsilon(\disc(k))$ once per degree,
accumulating to $\varepsilon(\disc(k))^{b}$ in degree $b$.

\emph{Consistency.} Applying the relation twice yields $\varepsilon(\disc(k))^{2b}$,
which must equal $1$ because $(\pi\ds)\ds = \pi$. By Lemma~\ref{lem:powtwo} every
even power of a quadratic character is trivial, and by Lemma~\ref{lem:evenb} the
exponent $2b$ is even, so the relation in degree $b$ follows.
\end{proof}

\begin{corollary}[Self-duality criterion]
If $\varepsilon(\disc(k))=1$ then $P^{b}(\pi\ds)=P^{b}(\pi)$ for all $\pi$. By
Euler's criterion this holds exactly when $\disc(k)$ is a quadratic residue.
\end{corollary}

\begin{corollary}[Parity dichotomy]
If $\varepsilon(\disc(k))=-1$ then $P^{b}(\pi\ds)=(-1)^{b}P^{b}(\pi)$, so the periods
agree when $b$ is even and are opposite when $b$ is odd. Over $\Q$, where
$b=\lfloor n^2/4\rfloor$, the sign flips exactly for $n\equiv 2 \pmod 4$.
\end{corollary}

\section{Applications and discussion}
The relation is a building block for the arithmetic theory of automorphic
$L$-functions. Functional equations relate $L(s,\pi)$ to $L(1-s,\pi\ds)$; tracking
rational structures across this reflection requires knowing how periods transform
under $\pi\mapsto\pi\ds$, and the discriminant twist is the correction term. The
hypothesis-minimal form proved here extends classical regular-weight statements and
shows the relation is forced by three abstract structural facts.

\section{Future directions}
\textbf{FD1.} The twist sign $\varepsilon(\disc(k))$ should equal the Kronecker symbol
$\chi_k(\disc(k))$, computable via quadratic reciprocity; self-duality
$\varepsilon(\disc)=1$ is, by Euler's criterion, "$\disc(k)$ is a quadratic residue".
\textbf{FD2.} For non-square discriminant, periods of $\pi$ and $\pi\ds$ agree iff $b$
is even; over $\Q$ disagreement occurs exactly for $n\equiv 2\pmod 4$.
\textbf{FD3.} Among all twist factors $c$, the relation is consistent with
$(\pi\ds)\ds=\pi$ for all $b$ iff $c^2=1$; quadraticity is forced by involutivity.
\textbf{FD4.} Under base change $k\to K$ the twist sign multiplies:
$\varepsilon_K(\disc(K))=\varepsilon_k(\disc(k))^{[K:k]}\cdot\varepsilon_k(\disc(K/k))$.

\section{Conclusion}
The Betti--Whittaker period of $\pi\ds$ equals that of $\pi$ times
$\varepsilon(\disc(k))^{b}$, the discriminant sign raised to the bottom cohomological
degree. The result follows from involutivity, quadraticity, and the closed
form/parity of $b$, collapsing a deep analytic comparison to a single parity
computation.

\end{document}

