from typing import List, Tuple

def bottom_degree(n: int, r1: int, r2: int) -> int:
    return r1 * ((n // 2) * ((n + 1) // 2)) + r2 * (n * (n - 1) // 2)

def degree_table(r1: int, r2: int, ns: List[int]) -> List[Tuple[int, int, str]]:
    out: List[Tuple[int, int, str]] = []
    for n in ns:
        b = bottom_degree(n, r1, r2)
        out.append((n, b, "even" if b % 2 == 0 else "odd"))
    return out

if __name__ == "__main__":
    print("GL(n) over Q (r1=1, r2=0): b = floor(n^2/4)")
    for n, b, p in degree_table(1, 0, list(range(1, 11))):
        print(f"  GL({n:2d}): b={b:3d} ({p})")

from typing import List

def quarter_square(n: int) -> int:
    return (n // 2) * ((n + 1) // 2)

def sign_flip_set_over_Q(max_n: int) -> List[int]:
    """Over Q with eps(disc) = -1, periods of pi and pi_dual flip sign exactly
    when b = floor(n^2/4) is odd, i.e. n == 2 (mod 4)."""
    return [n for n in range(1, max_n + 1) if quarter_square(n) % 2 == 1]

if __name__ == "__main__":
    flips = sign_flip_set_over_Q(30)
    print("n with sign flip:", flips)
    print("all == 2 (mod 4)?", all(n % 4 == 2 for n in flips))

