function DISCRIMINANT_TWIST(eps_disc, b):
    assert eps_disc in {+1, -1}
    if eps_disc == +1: return +1
    if b is odd: return -1 else return +1

function PERIOD_DUAL(period_pi, eps_disc, b):
    return DISCRIMINANT_TWIST(eps_disc, b) * period_pi
